SELECT paid_on, amount,
       SUM(amount) OVER (ORDER BY paid_on) AS running_total
FROM payments;

WITH RECURSIVE reports AS (
  SELECT id, name FROM employees WHERE id = 1
  UNION ALL
  SELECT e.id, e.name FROM employees e JOIN reports r ON e.manager_id = r.id
)
SELECT id, name FROM reports;

SELECT day, amount,
       amount - LAG(amount) OVER (ORDER BY day) AS change
FROM sales;
